/* Genere par tools/build-scenes.mjs — ne pas editer a la main.
   Source : web/scenes/*.glsl */

export const SCENE_IDS = ["drift","brume","abyss","eclipse","voidwell","monolith","grain","mandel","aube","pluie"];

export const SCENES_GLSL = "\n// ===== aube.glsl =====\n// ===========================================================================\n// aube.glsl -- LE SOLEIL QUI SE LEVE SUR DES CHAMPS\n//\n// La premiere scene chaude de l'application. Toutes les autres sont des gris\n// froids : c'etait cohérent tant que le decor ne servait qu'a accompagner ce\n// qui pese, mais il ne savait alors rien dire de ce qui va bien. « brume » dit\n// le calme -- la journee tient, rien ne presse. Ce n'est pas la meme chose que\n// l'espoir, qui est tourne vers ce qui vient.\n//\n// D'ou celle-ci : un horizon bas, des champs qui ondulent, et une lumiere qui\n// monte de derriere. Le soleil n'est jamais un disque net -- il n'est pas\n// arrive, il arrive, et c'est la difference que porte toute la scene.\n//\n// Cadre : uv.y de -0.5 en bas a +0.5 en haut, uv.x multiplie par le rapport\n// d'aspect. Le soleil est pose LEGEREMENT a gauche de l'axe pour laisser le\n// centre libre : c'est la que le texte se lit.\n//\n// e ne regle pas la luminosite, il regle la HAUTEUR du soleil et l'ampleur de\n// ce qui bouge : plus haut, plus ouvert.\n// ===========================================================================\n\nconst float aube_HZ = -0.20;    // la ligne des champs\nconst float aube_CX = -0.13;    // l'axe du soleil\n\n// Compression douce, comme partout ailleurs : rien ne depasse 0.27, et rien\n// n'est franchement ecrete -- une teinte chaude qui sature vire au blanc, et\n// un blanc dans le fond se bat avec le texte.\nvec3 aube_tone(vec3 c) {\n    c = max(c, 0.0);\n    return 0.27 * (1.0 - exp(-c / 0.27));\n}\n\n// Le profil des champs : deux ondes lentes et un fbm doux par-dessus. Ce sont\n// des ondulations de terrain, pas des montagnes -- l'amplitude reste petite.\nfloat aube_champ(float x, float t, float freq, float amp, float seed)\n{\n    float o = sin(x * freq + seed * 2.7) * 0.55\n            + sin(x * freq * 0.47 + seed * 5.1 + t * 0.013) * 0.45;\n    float g = (fbm(vec2(x * freq * 0.8 + seed * 17.0, seed * 4.0), 3) - 0.5) * 1.6;\n    return (o * 0.6 + g * 0.4) * amp;\n}\n\nvec3 scene_aube(vec2 uv, float t, float e)\n{\n    // La palette. Le haut reste presque noir -- c'est encore la nuit la-haut --\n    // et tout le chaud est concentre dans la bande de l'horizon.\n    vec3 ciel_haut = vec3(0.010, 0.014, 0.030);\n    vec3 ciel_bas  = vec3(0.115, 0.072, 0.048);\n    vec3 feu       = vec3(0.260, 0.150, 0.062);\n    vec3 terre     = vec3(0.030, 0.026, 0.022);\n\n    // e ouvre la scene : le soleil monte d'a peine trois centiemes de cadre,\n    // ce qui suffit -- toute la lumiere est dans le halo, pas dans le disque.\n    float haut = aube_HZ - 0.052 + 0.030 * e;\n    vec2  sp   = vec2(aube_CX, haut);\n\n    // ---- le ciel ----------------------------------------------------------\n    // Un degrade vertical, puis le halo par-dessus. Le degrade seul donnerait\n    // une bande horizontale uniforme : c'est le halo qui fait le lever.\n    /*\n     * LA BANDE CHAUDE RESTE BASSE. Etalee jusqu'a mi-hauteur, l'ambre remplit\n     * tout le cadre et il n'y a plus de nuit au-dessus : on perd le lever, il\n     * ne reste qu'un fond orange. C'est le CONTRASTE entre la nuit qui tient\n     * en haut et la lumiere qui monte en bas qui fait l'aube.\n     */\n    float v = smoothstep(0.26, aube_HZ - 0.04, uv.y);\n    vec3 col = mix(ciel_haut, ciel_bas, v * v);\n\n    // Le halo. Ecrase verticalement : la lumiere d'un soleil bas s'etale le\n    // long de l'horizon bien plus qu'elle ne monte.\n    vec2 d = (uv - sp) * vec2(0.62, 1.35);\n    float r = length(d);\n    float halo = exp(-r * 4.6) * 0.95 + exp(-r * 1.75) * 0.34;\n\n    // Le disque, jamais un bord : un noyau plus dense, dont la moitie basse\n    // est deja mangee par les champs.\n    float noyau = exp(-r * 12.0) * 0.9;\n\n    // Le voile de l'horizon : ce qui traine a plat de part et d'autre, et qui\n    // dit qu'il y a de l'air entre le soleil et nous.\n    float voile = exp(-abs(uv.y - aube_HZ) * 14.0) * exp(-abs(uv.x - aube_CX) * 1.1) * 0.34;\n\n    // Trois nappes de nuages tres etirees, qui derivent chacune a sa vitesse.\n    // Elles ne sont pas la pour faire joli : sans elles la lueur est un\n    // dégradé propre, et un dégradé propre ne ressemble a rien de vu.\n    float nu = 0.0;\n    for (int i = 0; i < 3; i++) {\n        float fi = float(i);\n        float y  = aube_HZ + 0.055 + fi * 0.075;\n        float n  = fbm(vec2(uv.x * (1.6 + fi * 0.7) + t * (0.009 + fi * 0.004) + fi * 23.0,\n                            uv.y * 5.0 + fi * 11.0), 3);\n        float bande = exp(-abs(uv.y - y) * (16.0 - fi * 3.0));\n        nu += bande * smoothstep(0.42, 0.78, n) * (0.30 - fi * 0.06);\n    }\n\n    col += feu * (halo + noyau) * (0.55 + 0.45 * e);\n    col += feu * voile;\n    // Les nuages ne s'ajoutent pas a la lumiere : ils la PORTENT. Multiplies\n    // par le halo, ils s'allument seulement la ou il y en a.\n    col += feu * nu * (0.35 + halo * 1.6);\n\n    // ---- les champs -------------------------------------------------------\n    // Quatre plans, du plus lointain au plus proche. Chacun mange le\n    // precedent ; le plus proche est presque noir, ce qui pose le cadre.\n    for (int i = 0; i < 4; i++) {\n        float fi = float(i);\n        float amp = 0.020 + fi * 0.013;\n        float freq = 2.3 + fi * 1.6;\n        float y0 = aube_HZ - fi * 0.052;\n        float h  = y0 + aube_champ(uv.x, t, freq, amp, fi + 1.0);\n\n        // Le bord se ferme sur deux pixels de cadre, pas plus : une crete\n        // floue a cette echelle ressemble a du brouillard, pas a un champ.\n        float m = smoothstep(h + 0.004, h - 0.004, uv.y);\n\n        // La crete attrape la lumiere qui vient de derriere. C'est le seul\n        // endroit ou les champs sont autre chose que du noir.\n        float lisiere = exp(-abs(uv.y - h) * 95.0);\n        float versSoleil = exp(-abs(uv.x - aube_CX) * 1.05);\n\n        vec3 plan = mix(terre * (1.0 - fi * 0.22), terre * 0.35, fi * 0.25);\n        plan += feu * lisiere * versSoleil * (0.72 - fi * 0.135) * (0.6 + 0.4 * e);\n\n        // Une brume basse posee dans le creux entre deux plans, qui respire.\n        float creux = smoothstep(h - 0.010, h - 0.070, uv.y);\n        plan += vec3(0.055, 0.042, 0.038) * creux * (0.30 - fi * 0.05)\n              * (0.55 + 0.45 * sin(t * 0.031 + fi * 1.9));\n\n        col = mix(col, plan, m);\n    }\n\n    // ---- la finition ------------------------------------------------------\n    // Le haut du cadre se perd dans le noir : le regard doit tomber vers\n    // l'horizon, pas partir en haut de l'ecran.\n    col *= mix(0.30, 1.0, smoothstep(0.52, -0.12, uv.y));\n\n    // Un souffle tres lent sur l'ensemble. Une minute et demie de periode :\n    // on ne le voit pas bouger, on le voit avoir bouge.\n    col *= 0.94 + 0.06 * sin(t * 0.068);\n\n    return aube_tone(col);\n}\n\n// ===== gravite.glsl =====\n// =====================================================================\n// GRAVITE  --  scenes abyss et monolith\n// Deux scenes de poids. Meme palette de gris froid a peine bleute,\n// meme brume en exponentielle de la hauteur, meme lenteur : aucun\n// coefficient de temps ne depasse 0.20, tout se compte en dizaines\n// de secondes. Meme finition : le haut du cadre se perd dans le noir,\n// compression douce, grain fixe contre le banding.\n// =====================================================================\n\n\n// ---------------------------------------------------------------------\n// ABYSS\n// Une pyramide lointaine posee sur une eau immobile qui la reflete.\n// Une seule lueur pale, juste au dessus du sommet. Ciel noir.\n// ---------------------------------------------------------------------\n\n// Geometrie fixe du cadre. Horizon tres bas, pyramide legerement a\n// droite de l axe pour laisser le centre libre : c est la que le\n// texte se lit.\nconst float abyss_HZ  = -0.48;   // ligne d eau\nconst float abyss_CX  =  0.26;   // axe de la pyramide\nconst float abyss_TOP = -0.155;  // hauteur du sommet\nconst float abyss_HW  =  0.42;   // demi base\n\n// Compression douce. Garantit qu aucune composante ne depasse 0.27,\n// sans jamais ecreter franchement.\nvec3 abyss_tone(vec3 c) {\n    c = max(c, 0.0);\n    return 0.27 * (1.0 - exp(-c / 0.27));\n}\n\n// Distance signee approchee a la silhouette de la pyramide.\n// Negatif dedans. Sert a la fois au masque et au filet des aretes.\nfloat abyss_pyr(vec2 p) {\n    float h = abyss_TOP - abyss_HZ;\n    vec2  q = vec2(abs(p.x - abyss_CX), p.y - abyss_HZ);\n    float l = sqrt(h * h + abyss_HW * abyss_HW);\n    float flank = (q.x * h + q.y * abyss_HW - abyss_HW * h) / l;\n    return max(flank, -q.y);\n}\n\n// Le ciel seul : un degrade qui s eteint en montant, un souffle de\n// nuage tres lent, et l unique source de lumiere de la scene.\nvec3 abyss_sky(vec2 p, float t, float e) {\n    float hgt  = max(p.y - abyss_HZ, 0.0);\n    float band = exp(-hgt * 4.6);\n    vec3  col  = vec3(0.026, 0.033, 0.046) * band * (0.60 + 0.40 * e);\n\n    // Nuage : derive de deux centiemes d unite par seconde.\n    float n = fbm(vec2(p.x * 1.6 + t * 0.010, p.y * 2.4 - t * 0.020), 3);\n    col += vec3(0.014, 0.017, 0.023) * band * (n - 0.5);\n\n    // La lueur : un halo large, puis un coeur pale et petit qui se\n    // pose juste au dessus de la pointe.\n    vec2  g = (p - vec2(abyss_CX, abyss_TOP + 0.020)) * vec2(1.10, 1.0);\n    float r = length(g);\n    float halo = exp(-r * 2.6) * 0.42 + exp(-r * 8.0) * 0.44;\n    col += vec3(0.50, 0.56, 0.68) * halo * (0.085 + 0.060 * e);\n    col += vec3(0.60, 0.66, 0.78) * exp(-r * 26.0) * (0.175 + 0.110 * e);\n    return col;\n}\n\n// Le monde au dessus de l eau : ciel plus pyramide. Appele une\n// seconde fois, en coordonnees miroir, pour fabriquer le reflet.\nvec3 abyss_field(vec2 p, float t, float e) {\n    vec3  col = abyss_sky(p, t, e);\n    float d   = abyss_pyr(p);\n\n    // Le bord est net au sommet et mange par la brume vers la base.\n    float low  = 1.0 - smoothstep(abyss_HZ, abyss_TOP, p.y);\n    float soft = 0.0035 + 0.030 * low;\n    float m    = 1.0 - smoothstep(-soft, soft, d);\n\n    // Face dans l ombre. L arete centrale separe deux valeurs a peine\n    // differentes : c est ce qui donne le volume, rien d autre.\n    float facet = smoothstep(-0.008, 0.008, p.x - abyss_CX);\n    vec3  face  = vec3(0.011, 0.013, 0.018) * mix(1.30, 0.70, facet)\n                * (0.45 + 0.55 * low);\n\n    // Filet de lumiere qui deborde sur les deux aretes hautes.\n    float rim = exp(-abs(d) * 110.0) * (1.0 - low * 0.85);\n    face += vec3(0.30, 0.34, 0.42) * rim * (0.040 + 0.045 * e);\n\n    return mix(col, face, m);\n}\n\nvec3 scene_abyss(vec2 uv, float t, float e) {\n    vec3 col = vec3(0.0);\n\n    if (uv.y > abyss_HZ) {\n        col = abyss_field(uv, t, e);\n    } else {\n        // Reflet : miroir autour de la ligne d eau. L ondulation est\n        // infime et respire sur une vingtaine de secondes ; a e nul\n        // l eau est une plaque.\n        float depth  = abyss_HZ - uv.y;                  // 0 a l horizon\n        float breath = 0.70 + 0.30 * sin(t * 0.11);\n        float amp    = (0.0014 + 0.0080 * e) * breath * (0.20 + depth * 1.5);\n\n        float w = sin(uv.x * 4.7 - t * 0.070) * 0.55\n                + sin(uv.x * 10.3 + t * 0.048) * 0.30;\n        w += (fbm(vec2(uv.x * 2.0, depth * 6.0 - t * 0.030), 3) - 0.5) * 1.6;\n\n        vec2 rp = vec2(uv.x + w * amp * 0.30, abyss_HZ + depth + w * amp);\n        col  = abyss_field(rp, t, e) * (0.52 - 0.34 * smoothstep(0.0, 0.60, depth));\n        col += vec3(0.006, 0.008, 0.012) * exp(-depth * 0.9);\n\n        // Chemin de lumiere sous la lueur, brise par de fines rides.\n        // Il rend le bas du cadre un peu plus present que le haut.\n        float axis = exp(-abs(uv.x - abyss_CX) * (3.0 + depth * 2.4));\n        float rid  = 0.5 + 0.5 * sin(depth * 42.0 - t * 0.20 + w * 1.1);\n        rid = rid * rid * rid;\n        col += vec3(0.40, 0.46, 0.56) * axis * rid\n             * exp(-depth * 1.6) * (0.030 + 0.028 * e);\n    }\n\n    // Voile de brume au ras de l eau. Meme grammaire que monolith :\n    // exponentielle de la distance au sol, module par un fbm lent,\n    // eclaire seulement du cote de la source. Il retombe plus loin\n    // sous l horizon qu au dessus : c est la distance qui l epaissit.\n    float above = max(uv.y - abyss_HZ, 0.0);\n    float below = max(abyss_HZ - uv.y, 0.0);\n    float mist  = exp(-above * 9.0 - below * 4.0);\n    mist *= 0.40 + 0.95 * fbm(vec2(uv.x * 1.6 + t * 0.010,\n                                   uv.y * 2.4 - t * 0.020), 4);\n    float lit = exp(-abs(uv.x - abyss_CX) * 1.5);\n    col = mix(col, vec3(0.038, 0.045, 0.058) * (0.30 + 0.90 * lit),\n              clamp(mist * (0.30 + 0.20 * e), 0.0, 0.52));\n\n    // Le haut se perd dans le noir, les bords reculent.\n    col *= 1.0 - 0.45 * smoothstep(0.10, 1.00, uv.y);\n    col *= 1.0 - 0.28 * smoothstep(0.60, 1.70, length(vec2(uv.x * 0.70, uv.y * 0.60)));\n\n    col  = abyss_tone(col);\n    col += (hash21(uv * vec2(443.7, 271.9)) - 0.5) * 0.0010;\n    return max(col, 0.0);\n}\n\n\n// ---------------------------------------------------------------------\n// MONOLITH\n// Une dalle verticale, nette, plantee au centre bas d un sol brumeux.\n// Quelques marches a son pied. Lumiere rasante venant de derriere, qui\n// detache la silhouette sans jamais eclairer sa face.\n// ---------------------------------------------------------------------\n\nconst float monolith_G  = -0.44;   // ligne de sol au pied de la dalle\nconst float monolith_CX =  0.015;  // axe de la dalle, quasi centre\nconst float monolith_HW =  0.150;  // demi largeur\nconst float monolith_LX = -0.22;   // la source, derriere et a gauche\n\n// Meme compression que abyss, meme plafond.\nvec3 monolith_tone(vec3 c) {\n    c = max(c, 0.0);\n    return 0.27 * (1.0 - exp(-c / 0.27));\n}\n\n// Silhouette de la dalle : une boite sans couvercle, qui sort du\n// cadre par le haut en se resserrant a peine.\nfloat monolith_slab(vec2 p) {\n    float k  = clamp((p.y - monolith_G) / 1.8, 0.0, 1.0);\n    float hw = monolith_HW * (1.0 - 0.10 * k);\n    return max(abs(p.x - monolith_CX) - hw, monolith_G - p.y);\n}\n\n// L air derriere la dalle : meme degrade que le ciel d abyss, meme\n// nuage lent, plus le lobe de lumiere rasante.\nvec3 monolith_air(vec2 p, float t, float e) {\n    float hgt  = max(p.y - monolith_G, 0.0);\n    float band = exp(-hgt * 3.0);\n    vec3  col  = vec3(0.024, 0.030, 0.042) * band * (0.60 + 0.40 * e);\n\n    float n = fbm(vec2(p.x * 1.6 + t * 0.010, p.y * 2.4 - t * 0.020), 3);\n    col += vec3(0.013, 0.016, 0.021) * band * (n - 0.5);\n\n    // Lobe tres etale horizontalement et ecrase en hauteur : la\n    // lumiere arrive au ras du sol. Son coeur passe derriere la dalle.\n    vec2  g  = (p - vec2(monolith_LX, monolith_G + 0.06)) * vec2(0.55, 1.60);\n    float lo = exp(-length(g) * 2.0);\n    col += vec3(0.44, 0.50, 0.62) * lo * (0.105 + 0.075 * e);\n    col += vec3(0.52, 0.58, 0.70) * exp(-length(g) * 6.0) * (0.070 + 0.055 * e);\n    return col;\n}\n\nvec3 scene_monolith(vec2 uv, float t, float e) {\n    vec3 col = monolith_air(uv, t, e);\n\n    // Le sol : plan sombre que la lumiere frole sans l eclairer. Le\n    // bord est large, et une veine de contact l adoucit encore : c est\n    // le meme geste que le voile pose sur l horizon d abyss.\n    float depth = max(monolith_G - uv.y, 0.0);\n    vec3  grnd  = vec3(0.014, 0.017, 0.023) * exp(-depth * 0.9);\n    float smear = exp(-abs(uv.x - monolith_LX) * 1.1) * exp(-depth * 2.6);\n    grnd += vec3(0.26, 0.30, 0.38) * smear * (0.030 + 0.022 * e);\n    float gm = 1.0 - smoothstep(-0.022, 0.012, uv.y - monolith_G);\n    col = mix(col, grnd, gm);\n    float gline = exp(-abs(uv.y - monolith_G) * 22.0)\n                * exp(-abs(uv.x - monolith_LX) * 0.9);\n    col += vec3(0.22, 0.26, 0.33) * gline * (0.030 + 0.020 * e);\n\n    // La dalle. Sa face reste noire ; seule l arete cote source la\n    // detache du fond, et plus fort en bas qu en haut.\n    float d  = monolith_slab(uv);\n    float sm = 1.0 - smoothstep(-0.004, 0.004, d);\n    float lean  = smoothstep(-monolith_HW, monolith_HW, uv.x - monolith_CX);\n    float rfall = exp(-max(uv.y - monolith_G, 0.0) * 0.95);\n    // la pierre suit exactement la decroissance de l air, deux a quatre\n    // fois plus sombre : jamais plus claire que le fond, et le haut de\n    // la dalle se dissout dans le noir sans qu on voie de bord\n    float sband = exp(-max(uv.y - monolith_G, 0.0) * 3.0);\n    vec3  slab  = vec3(0.024, 0.030, 0.042) * sband * mix(0.42, 0.22, lean);\n\n    float rim   = exp(-abs(d) * 150.0);\n    float rside = 1.0 - smoothstep(-0.020, 0.000, uv.x - monolith_CX);\n    slab += vec3(0.30, 0.34, 0.44) * rim * (0.30 + 0.70 * rside)\n          * rfall * (0.045 + 0.040 * e);\n    col = mix(col, slab, sm);\n\n    // Quatre marches : chacune plus basse et plus large que la\n    // precedente, donc plus proche. Seule leur arete se voit.\n    for (int i = 0; i < 4; i++) {\n        float fi = float(i);\n        float ty = monolith_G - 0.030 - 0.042 * fi;\n        float hw = 0.200 + 0.062 * fi;\n        float mx = 1.0 - smoothstep(hw - 0.005, hw + 0.005, abs(uv.x - monolith_CX));\n        float my = 1.0 - smoothstep(ty - 0.004, ty + 0.004, uv.y);\n        float m  = mx * my;\n\n        vec3 tread = vec3(0.0085, 0.0105, 0.0145) * (1.0 - 0.12 * fi);\n        col = mix(col, tread, m * 0.94);\n\n        float lip  = exp(-max(ty - uv.y, 0.0) * 22.0) * m;\n        float edge = exp(-abs(uv.y - ty) * 150.0) * mx;\n        float side = exp(-abs(uv.x - monolith_LX) * 0.8);\n        col += vec3(0.30, 0.34, 0.42) * side * (edge * (0.034 + 0.026 * e)\n                                              + lip * (0.010 + 0.008 * e));\n    }\n\n    // La brume. C est elle que e fait varier : sa hauteur le long de\n    // la dalle et sa densite. Meme fbm, meme derive que dans abyss.\n    float rise = 0.28 + 0.46 * e;\n    float hgt  = max(uv.y - (monolith_G - 0.30), 0.0);\n    float dens = exp(-hgt / rise);\n    dens *= 0.40 + 1.05 * fbm(vec2(uv.x * 1.6 + t * 0.010,\n                                   uv.y * 2.4 - t * 0.020), 4);\n    float lit  = exp(-length((uv - vec2(monolith_LX, monolith_G))\n                             * vec2(0.50, 1.30)) * 1.6);\n    vec3  fogc = vec3(0.042, 0.050, 0.064) * (0.30 + 1.20 * lit);\n    col = mix(col, fogc, clamp(dens * (0.42 + 0.30 * e), 0.0, 0.80));\n\n    // Meme finition que abyss, au coefficient pres. Le sol s eteint en\n    // revenant vers nous, comme l eau s eteint en approchant.\n    col *= 1.0 - 0.26 * (1.0 - smoothstep(-1.05, -0.70, uv.y));\n    col *= 1.0 - 0.45 * smoothstep(0.10, 1.00, uv.y);\n    col *= 1.0 - 0.28 * smoothstep(0.60, 1.70, length(vec2(uv.x * 0.70, uv.y * 0.60)));\n\n    col  = monolith_tone(col);\n    col += (hash21(uv * vec2(443.7, 271.9)) - 0.5) * 0.0010;\n    return max(col, 0.0);\n}\n\n// ===== infini.glsl =====\n// =====================================================================\n//  INFINI  --  deux scenes de vertige : mandel et drift.\n//\n//  Meme main pour les deux. Meme rampe de gris (cendre froide, gris,\n//  os a peine tiede), meme lampe unique et faible posee en bas a\n//  droite hors du champ de lecture, meme voile qui mange le haut de\n//  l'image, meme creux au centre pour que le texte s'y lise, meme\n//  grain fixe contre le banding, et la meme lenteur : tout ce qui\n//  bouge ici se compte en dizaines de secondes.\n//\n//  Attention : scene_drift remplace celle de defaut.glsl. Les deux ne\n//  peuvent pas cohabiter dans le meme bundle.\n// =====================================================================\n\n\n// ---------------------------------------------------------------------\n//  MANDEL\n//  L'ensemble de Mandelbrot traite comme une gravure : une plaque\n//  sombre, un trait fin, et un zoom qui ne finit jamais.\n//\n//  Le cadre est pose sur le point de Misiurewicz c = i, un bord\n//  filamenteux ou l'ensemble est asymptotiquement auto-similaire sous\n//  z -> lambda * z, avec lambda = 4 + 4i. Une periode de zoom divise\n//  donc l'echelle par |lambda| = 5.656854 et tourne de\n//  arg(lambda) = PI/4 : au bout d'une periode l'image est revenue sur\n//  elle-meme, le cycle se referme sans raccord visible et la descente\n//  peut durer toute la soiree. C'est la crise existentielle : le meme\n//  motif a toutes les echelles, et pas de fond.\n// ---------------------------------------------------------------------\n\n// La rampe tonale commune aux deux scenes. Le noir n'est jamais un\n// vrai noir mais une cendre froide ; la lumiere n'est jamais blanche\n// mais un os a peine tiede. Plafond a 0.108 : le trait doit rester un\n// trait d'argent, pas une rayure blanche.\nvec3 mandel_tone(float v) {\n    v = clamp(v, 0.0, 1.0);\n    vec3 ash  = vec3(0.0075, 0.0100, 0.0155);\n    vec3 grey = vec3(0.0330, 0.0370, 0.0450);\n    vec3 bone = vec3(0.1080, 0.1030, 0.0900);\n    vec3 col  = mix(ash, grey, smoothstep(0.0, 0.55, v));\n    return mix(col, bone, smoothstep(0.52, 1.0, v));\n}\n\n// Produit de deux complexes.\nvec2 mandel_cmul(vec2 a, vec2 b) {\n    return vec2(a.x * b.x - a.y * b.y, a.x * b.y + a.y * b.x);\n}\n\n// Exponentielle decroissante bornee : sert a tous les degrades de la\n// scene. Le min evite de demander a exp() des valeurs absurdes.\nfloat mandel_fall(float a) {\n    return exp(-min(a, 50.0));\n}\n\n// Ce qui reste de matiere a cette hauteur : 1 en bas, presque rien en\n// haut. Applique a la couleur finale, donc le haut du cadre tombe\n// vraiment dans le noir.\nfloat mandel_ciel(vec2 uv) {\n    return 0.28 + 0.72 * (1.0 - smoothstep(-1.00, 0.95, uv.y));\n}\n\n// Le creux central : sous la colonne de lecture on garde tres peu de\n// contraste. L'hote pose deja son propre voile la ; celui-ci ne fait\n// que l'accompagner.\nfloat mandel_centre(vec2 uv) {\n    return mix(0.50, 1.0, smoothstep(0.10, 1.05, length(uv * vec2(0.58, 1.0))));\n}\n\n// L'unique source : basse, a droite, tres etalee. Elle n'eclaire rien\n// franchement, elle dit seulement de quel cote se trouve le jour.\nfloat mandel_lampe(vec2 uv) {\n    vec2 p = uv - vec2(0.42, -0.86);\n    return mandel_fall(dot(p, p) * 0.60);\n}\n\nvec3 scene_mandel(vec2 uv, float t, float e) {\n    // Phase du zoom. e n'accelere qu'a peine : 78 s par periode au\n    // repos, 60 s a pleine energie.\n    float period = 78.0 - 18.0 * e;\n    float x = fract(t / period);\n    float s  = 0.0030 * exp(-1.7328680 * x);   // exp(-log|lambda| * x)\n    float th = -0.7853982 * x;                 // -arg(lambda) * x\n\n    // Le point de fuite est tenu bas et a droite, du cote de la lampe :\n    // le tronc du filament est eclaire, ses ramures se perdent en\n    // montant vers la gauche.\n    vec2 d = mandel_cmul(vec2(cos(th), sin(th)) * s, uv - vec2(0.22, -0.58));\n    vec2 c = vec2(0.0, 1.0) + d;\n\n    // Iteration avec sa derivee : estimateur de distance a l'ensemble.\n    // 56 tours, pas un de plus, et aucune borne variable.\n    vec2  z  = vec2(0.0, 0.0);\n    vec2  dz = vec2(0.0, 0.0);\n    float n  = 0.0;\n    float r2 = 0.0;\n    for (int i = 0; i < 56; i++) {\n        if (r2 < 4096.0) {\n            dz = 2.0 * mandel_cmul(z, dz) + vec2(1.0, 0.0);\n            z  = mandel_cmul(z, z) + c;\n            r2 = dot(z, z);\n            n += 1.0;\n        }\n    }\n\n    float esc = step(4096.0, r2);\n    float r   = sqrt(max(r2, 1.0e-12));\n    float de  = r * max(log(r), 1.0e-4) / max(length(dz), 1.0e-12);\n\n    // Largeur ramenee en unites d'ecran : le trait garde exactement la\n    // meme finesse a toutes les profondeurs, ce qui est la condition\n    // pour que la boucle ne se voie pas.\n    float w = de / s;\n\n    // Le burin : un trait fin, un liseret, puis une brume large\n    // accrochee au trait. C'est cette brume qui donne la profondeur.\n    float ink = mandel_fall(w * 230.0) * 0.90\n              + mandel_fall(w *  42.0) * 0.14\n              + mandel_fall(w *   9.0) * 0.05;\n    ink = mix(0.42, ink, esc);\n\n    // Les 56 tours ne suffisent plus passe une certaine finesse. Plutot\n    // que de laisser ces pixels s'empater, on les eteint en douceur.\n    // Le compte est corrige de la derive du cycle (une periode ajoute\n    // exactement deux iterations), sans quoi le fondu deriverait et la\n    // boucle se verrait.\n    float deep = 1.0 - smoothstep(34.0, 52.0, n - 2.0 * x);\n    ink *= deep;\n\n    // Hachure tiree du compte d'iteration lisse : la texture de la\n    // plaque. Amplitude minuscule, et serree contre le motif pour ne\n    // pas grisailler le reste du cadre.\n    float nu = n + 1.0 - log(max(log(r), 1.0)) * 1.4426950;\n    float hatch = (0.5 + 0.5 * cos(nu * 2.4)) * 0.030 * esc * deep\n                * mandel_fall(w * 2.5);\n\n    // La distance a la lampe fait le reste de la profondeur : les\n    // ramures lointaines s'effacent presque completement.\n    float lampe = mandel_lampe(uv);\n    ink *= 0.30 + 1.05 * lampe;\n\n    // e ne monte pas la lumiere : il fait sortir les filaments.\n    float centre = mandel_centre(uv);\n    float v = (ink + hatch) * (0.55 + 0.45 * e) * centre;\n    v += lampe * 0.16 * centre + 0.020;\n\n    // Grain de plaque, fixe dans le temps : rien ne scintille.\n    v += (hash21(uv * 613.0) - 0.5) * 0.010;\n\n    return mandel_tone(v) * mandel_ciel(uv);\n}\n\n\n// ---------------------------------------------------------------------\n//  DRIFT\n//  Un champ d'etoiles tres faible qui glisse lateralement, un ruban\n//  laiteux en diagonale sous la ligne de lecture, et deux ou trois\n//  grandes masses de poussiere qui passent devant. C'est le\n//  detachement : on pense a tres grand, et plus rien n'a de taille.\n// ---------------------------------------------------------------------\n\n// Meme rampe que mandel, au chiffre pres.\nvec3 drift_tone(float v) {\n    v = clamp(v, 0.0, 1.0);\n    vec3 ash  = vec3(0.0075, 0.0100, 0.0155);\n    vec3 grey = vec3(0.0330, 0.0370, 0.0450);\n    vec3 bone = vec3(0.1080, 0.1030, 0.0900);\n    vec3 col  = mix(ash, grey, smoothstep(0.0, 0.55, v));\n    return mix(col, bone, smoothstep(0.52, 1.0, v));\n}\n\nfloat drift_fall(float a) {\n    return exp(-min(a, 50.0));\n}\n\n// Memes finitions que mandel.\nfloat drift_ciel(vec2 uv) {\n    return 0.28 + 0.72 * (1.0 - smoothstep(-1.00, 0.95, uv.y));\n}\n\nfloat drift_centre(vec2 uv) {\n    return mix(0.62, 1.0, smoothstep(0.10, 1.05, length(uv * vec2(0.58, 1.0))));\n}\n\nfloat drift_lampe(vec2 uv) {\n    vec2 p = uv - vec2(0.42, -0.86);\n    return drift_fall(dot(p, p) * 0.60);\n}\n\n// Une nappe d'etoiles. Une cellule porte au plus une etoile ; sa\n// position, sa taille et sa magnitude sortent du hash de la cellule et\n// ne dependent jamais du temps. Une etoile ne peut donc que se\n// translater : rien ne clignote dans le champ peripherique. Le\n// decalage reste a l'interieur de la cellule, ce qui evite d'avoir a\n// visiter les voisines et empeche tout bord coupe.\nfloat drift_nappe(vec2 q, float dens, float seed, float seuil, float taille) {\n    vec2  g  = q * dens;\n    vec2  id = floor(g);\n    vec2  f  = fract(g) - 0.5;\n    float h1 = hash21(id + vec2(seed,            seed * 1.7 +  3.1));\n    float h2 = hash21(id + vec2(seed * 2.3 + 17.9, seed * 0.6 +  5.4));\n    float h3 = hash21(id + vec2(seed * 0.9 + 41.2, seed * 3.1 + 29.7));\n\n    vec2  off = (vec2(h2, h3) - 0.5) * 0.66;\n    float d   = length(f - off) / dens;         // distance en unites d'ecran\n    float sg  = (0.0032 + 0.0024 * h3) * taille;\n    float k   = d / sg;\n    float k2  = k * k;\n\n    // Beaucoup de faibles, quelques vives : c'est la distribution des\n    // magnitudes qui fait qu'un ciel n'est pas une trame.\n    float mag = 0.10 + 0.90 * h2 * h2;\n    return step(seuil, h1) * mag * (drift_fall(k2) + drift_fall(k2 * 0.35) * 0.035);\n}\n\nvec3 scene_drift(vec2 uv, float t, float e) {\n    // e ne change que la vitesse de derive : de six millemes d'unite\n    // par seconde au repos a deux centiemes a pleine energie.\n    float sp   = 0.0060 + 0.0165 * e;\n    float dx   = t * sp;\n    float sway = sin(t * 0.019) * 0.028;        // une respiration, pas un mouvement\n\n    // Trois nappes, chacune sur sa grille tournee pour qu'aucun reseau\n    // ne se devine, et a sa propre vitesse : c'est la parallaxe qui\n    // creuse le fond. Le decalage est applique avant la rotation, donc\n    // les trois glissent bien dans le meme sens a l'ecran.\n    vec2 q1 = rot(0.21) * (uv + vec2(-dx * 1.00, sway));\n    vec2 q2 = rot(1.03) * (uv + vec2(-dx * 0.62, sway * 0.70));\n    vec2 q3 = rot(2.27) * (uv + vec2(-dx * 0.33, sway * 0.45));\n    float st = drift_nappe(q1, 14.0,  1.0, 0.80, 1.00) * 1.00\n             + drift_nappe(q2, 20.0,  7.0, 0.76, 0.86) * 0.62\n             + drift_nappe(q3, 27.0, 19.0, 0.72, 0.74) * 0.38;\n\n    // Le ruban : la voie laiteuse, en diagonale douce et tenue sous le\n    // centre du cadre. C'est la silhouette de la scene, celle qu'on\n    // reconnait sans regarder.\n    float bc   = (rot(-0.42) * uv).y + 0.42;\n    float band = drift_fall(bc * bc * 5.0);\n    st *= 0.18 + 1.15 * band;\n\n    // Deux grandes masses et une plus petite, plus proches que les\n    // etoiles donc plus rapides. Les seuils sont serres autour de la\n    // moyenne du fbm : chaque masse ne couvre qu'un quart du cadre, et\n    // ce quart respire au fil de la derive.\n    float n1 = smoothstep(0.550, 0.615,\n               fbm(vec2(uv.x * 0.75 - dx * 1.45 + 11.3,\n                        uv.y * 0.75 + sway * 0.90 +  4.1), 4));\n    float n2 = smoothstep(0.540, 0.620,\n               fbm(vec2(uv.x * 1.15 - dx * 1.05 - 27.5,\n                        uv.y * 1.15 - sway * 0.60 + 18.9), 4));\n    float n3 = smoothstep(0.540, 0.650,\n               fbm(vec2(uv.x * 1.90 - dx * 2.10 + 41.7,\n                        uv.y * 1.90 + sway * 1.30 -  8.3), 3));\n    float dust = clamp(n1 * 0.85 + n2 * 0.55 + n3 * 0.32, 0.0, 1.0);\n\n    // Elles passent devant : elles mangent les etoiles et le ruban.\n    st *= 1.0 - 0.55 * dust;\n    float ruban = band * (0.55 + 0.45 * n2) * (1.0 - 0.85 * dust) * 0.30;\n\n    // Loin de la lampe un nuage n'est qu'une absence ; pres d'elle il\n    // prend un peu de jour. Meme lampe que mandel, au meme endroit.\n    float lampe = drift_lampe(uv);\n    float nuage = dust * (0.030 + 0.28 * lampe);\n\n    float centre = drift_centre(uv);\n    float v = (st * 1.90 + ruban + nuage) * centre;\n    v += lampe * 0.10 * centre + 0.010;\n\n    // Meme grain que mandel.\n    v += (hash21(uv * 613.0) - 0.5) * 0.010;\n\n    return drift_tone(v) * drift_ciel(uv);\n}\n\n// ===== meteo.glsl =====\n// ===========================================================================\n// meteo.glsl -- deux etats interieurs : BRUME et GRAIN\n//\n// Meme main pour les deux : la meme gamme de gris froids, la meme lueur\n// voilee a peine tiede, la meme brume en exponentielle de la distance a une\n// ligne, la meme lenteur (rien ne varie a plus de 0.14 Hz, tout se compte en\n// dizaines de secondes), la meme finition (le haut se perd dans le noir,\n// tramage fixe contre le banding, plafond dur a 0.26).\n//\n// Cadre : la hauteur de l'ecran vaut une unite, uv.y va de -0.5 en bas a\n// +0.5 en haut, uv.x est multiplie par le rapport d'aspect (donc environ\n// +-0.25 sur un telephone, +-0.9 sur un ecran large). Les deux sources sont\n// posees vers le bord gauche : sur un telephone elles sortent du cadre et il\n// n'en reste que la nappe qu'elles eclairent. C'est voulu -- une lumiere hors\n// champ ne tire jamais l'oeil hors du texte.\n// ===========================================================================\n\n\n// ---------------------------------------------------------------------------\n// BRUME\n// Cinq couches de montagnes en fbm : pale au fond, noir au premier plan, une\n// nappe de brume couchee sur chaque crete. C'est la scene des bons soirs :\n// la plus douce, celle qui ne demande rien.\n//\n// Lumiere : une lune voilee, en haut a gauche, juste au-dessus de la crete la\n// plus lointaine, plus la trainee qu'elle laisse le long de l'horizon.\n// e : la hauteur de la brume entre les couches (elle monte et redescend), la\n// respiration des cretes, et ce que la lune arrive a traverser.\n// ---------------------------------------------------------------------------\n\n// Profil d'une crete. Une tranche de fbm etiree horizontalement, pointes\n// adoucies : des montagnes, pas des dents de scie. Retourne environ [-0.5,0.5].\nfloat brume_ridge(vec2 uv, float freq, float drift, float seed)\n{\n    float x = uv.x * freq + drift + seed * 31.7;\n    // Le fbm est resserre autour de 0.5 : on l'etale, sinon la crete est\n    // une ligne presque droite.\n    float h = (fbm(vec2(x, seed * 9.3), 4) - 0.5) * 2.2;\n    return h * 0.80 + 0.20 * sin(x * 0.65 + seed * 2.1);\n}\n\nvec3 scene_brume(vec2 uv, float t, float e)\n{\n    // Palette commune aux deux scenes.\n    vec3 ciel_haut = vec3(0.004, 0.005, 0.009);\n    vec3 ciel_bas  = vec3(0.021, 0.026, 0.036);\n    vec3 brume_col = vec3(0.088, 0.101, 0.122);\n    vec3 lueur_col = vec3(0.228, 0.214, 0.194);\n\n    // Ciel : le haut se perd dans le noir, l'horizon garde un peu de matiere.\n    float v = smoothstep(0.55, -0.25, uv.y);\n    vec3 col = mix(ciel_haut, ciel_bas, v * v);\n\n    // e n'est pas un curseur de luminosite : il decide de ce que la lueur\n    // arrive a traverser, et de l'amplitude de tout ce qui bouge.\n    float pres = 0.55 + 0.45 * e;\n\n    // La source : une lune voilee, decalee a gauche, posee juste au-dessus de\n    // la crete la plus lointaine. Jamais un disque net, jamais un bord.\n    vec2  lp = vec2(-0.22, 0.24);\n    float ld = length((uv - lp) * vec2(1.0, 1.25));\n    float halo = exp(-ld * 3.4) * 0.40 + exp(-ld * 9.5) * 0.30;\n    // Sa trainee le long de l'horizon, tres etalee : c'est elle qui detache\n    // les silhouettes de loin.\n    halo += exp(-abs(uv.y - 0.10) * 6.2) * exp(-abs(uv.x + 0.16) * 1.1) * 0.24;\n    col += lueur_col * halo * pres;\n\n    // Les cinq couches, du fond vers le premier plan.\n    for (int i = 0; i < 5; i++)\n    {\n        float fi = float(i);\n        float k  = fi / 4.0;              // 0.0 = fond, 1.0 = premier plan\n        float kk = k * (1.45 - 0.45 * k); // la valeur tombe vite des la 2e couche\n\n        // Plus une couche est proche, plus elle est basse, ample et lente :\n        // c'est le seul indice de profondeur, il doit etre net.\n        float base  = mix( 0.200, -0.340, k);\n        float amp   = mix( 0.090,  0.340, k);\n        float freq  = mix( 6.000,  1.600, k);\n        float drift = t * mix(0.0040, 0.0160, k);\n\n        // Respiration : les cretes montent et descendent de quelques pixels.\n        base += sin(t * 0.055 + fi * 1.7) * 0.008 * (0.35 + 0.65 * e);\n\n        float hgt = base + amp * brume_ridge(uv, freq, drift, fi + 1.0);\n\n        // Silhouette : de plus en plus noire vers l'avant.\n        vec3 lay = mix(vec3(0.088, 0.100, 0.121), vec3(0.004, 0.005, 0.008), kk);\n        // Le flanc tourne vers la lune garde un reste de lumiere rasante.\n        lay += lueur_col * 0.08 * (1.0 - k) * exp(-abs(uv.x + 0.16) * 1.4) * pres;\n\n        // Volume : le flanc s'assombrit en descendant sous la crete. Sans ca\n        // les couches se lisent comme des bandes plates empilees.\n        lay *= mix(1.0, 0.60, smoothstep(0.0, 0.30, hgt - uv.y));\n        // Les couches ne sont visibles que par la lumiere qui les atteint :\n        // a e nul la montagne rentre dans le noir avec le reste.\n        lay *= 0.70 + 0.30 * e;\n\n        // Bord net devant, mange par l'air au fond.\n        float edge = mix(0.0060, 0.0025, k);\n        float m = smoothstep(-edge, edge, hgt - uv.y);\n        col = mix(col, lay, m);\n\n        // La brume couchee sur la crete. C'est ce que e fait varier : la\n        // nappe monte entre les couches quand la journee pese, et elle\n        // respire par-dessus sur une vingtaine de secondes.\n        float above = uv.y - hgt;\n        float hh = mix(0.012, 0.045, e) * (1.0 + 0.30 * e * sin(t * 0.062 + fi * 1.1));\n        float band = exp(-max(above, 0.0) / hh) * smoothstep(-hh * 1.6, 0.0, above);\n        float tex  = 0.55 + 0.60 * fbm(vec2(uv.x * 2.2 + t * 0.010 + fi * 5.0, fi * 3.0), 2);\n        float amt  = band * tex * mix(0.42, 0.10, k) * (0.60 + 0.40 * e);\n        // La nappe se teinte de la lueur quand elle passe devant la lune.\n        vec3 bc = mix(brume_col, lueur_col * 0.72,\n                      exp(-abs(uv.x + 0.16) * 1.2) * 0.50 * pres);\n        col = mix(col, bc, clamp(amt, 0.0, 1.0));\n    }\n\n    // Fond de vallee : le bas ne tombe jamais tout a fait dans le noir, il\n    // reste un peu plus present que le haut.\n    col += brume_col * 0.07 * smoothstep(-0.12, -0.55, uv.y) * (0.45 + 0.55 * e);\n\n    // Tramage fixe en espace ecran : casse les bandes des degrades tres\n    // sombres sans jamais bouger d'une image a l'autre.\n    col += (hash21(uv * 511.0) - 0.5) * 0.004;\n\n    return clamp(col, 0.0, 0.26);\n}\n\n\n// ---------------------------------------------------------------------------\n// GRAIN\n// Un grain numerique qui ne tient pas en place : des cellules qui naissent et\n// meurent sur une grille deformee, des bandes horizontales qui se decalent,\n// des lignes de balayage a peine visibles. C'est l'anxiete.\n//\n// Rien ne clignote : chaque cellule a sa propre periode, entre 7 et 19\n// secondes, soit 0.05 a 0.14 Hz. L'instabilite se lit dans le fait que le\n// motif ne repasse jamais deux fois par le meme etat, pas dans une frequence.\n//\n// Lumiere : la meme lueur voilee que dans BRUME, tombee en bas a gauche,\n// comme si elle passait derriere l'ecran.\n// e : la densite des cellules, et ce que la lueur traverse.\n// ---------------------------------------------------------------------------\n\n// Une nappe de cellules. cs = taille d'une cellule (plus large que haute :\n// c'est une grille de caracteres, pas un damier), dens = fraction vivante.\nfloat grain_cells(vec2 p, float t, vec2 cs, float dens, float seed)\n{\n    vec2 g  = p / cs;\n    vec2 id = floor(g);\n    vec2 f  = fract(g) - 0.5;\n\n    float ha = hash21(id + seed);\n    float hb = hash21(id * 1.31 + seed + 7.3);\n    float hc = hash21(id * 0.77 + seed + 19.1);\n\n    // Seuil : seule une fraction des cellules a le droit de vivre.\n    float live = smoothstep(1.0 - dens - 0.07, 1.0 - dens + 0.07, hc);\n\n    // Periode propre a chaque cellule, et phase propre : deux voisines ne\n    // s'allument jamais ensemble et l'ensemble ne boucle pas.\n    float per = 7.0 + 12.0 * ha;\n    float x = fract(t / per + hb);\n    float env = smoothstep(0.0, 0.30, x) * smoothstep(1.0, 0.68, x);\n\n    // Forme : un pave a bords doux, parfois etroit, parfois plein.\n    float w = mix(0.30, 0.46, step(0.55, hb));\n    vec2  q = abs(f) - vec2(w, 0.30);\n    float d = max(q.x, q.y);\n    float shape = smoothstep(0.09, -0.03, d);\n\n    return shape * env * live * (0.45 + 0.55 * hb);\n}\n\n// Decalage lateral par bandes horizontales. La valeur change toutes les neuf\n// secondes avec un fondu de pres de deux secondes : le motif se defait, mais\n// rien ne saute d'une image a l'autre.\nfloat grain_rowshift(float row, float t)\n{\n    float s  = t / 9.0;\n    float i0 = floor(s);\n    float fr = s - i0;\n    float a = hash21(vec2(row, i0));\n    float b = hash21(vec2(row, i0 + 1.0));\n    return (mix(a, b, smoothstep(0.80, 1.0, fr)) - 0.5) * 0.16;\n}\n\nvec3 scene_grain(vec2 uv, float t, float e)\n{\n    // Meme palette que BRUME, au centieme pres.\n    vec3 ciel_haut = vec3(0.004, 0.005, 0.009);\n    vec3 ciel_bas  = vec3(0.019, 0.023, 0.033);\n    vec3 brume_col = vec3(0.088, 0.101, 0.122);\n    vec3 lueur_col = vec3(0.228, 0.214, 0.194);\n\n    float v = smoothstep(0.55, -0.25, uv.y);\n    vec3 col = mix(ciel_haut, ciel_bas, v * v);\n\n    float pres = 0.55 + 0.45 * e;\n\n    // La source, tombee en bas a gauche et deja mangee par la brume.\n    vec2  lp = vec2(-0.30, -0.32);\n    float ld = length((uv - lp) * vec2(1.0, 1.35));\n    float halo = exp(-ld * 4.4) * 0.40 + exp(-ld * 11.0) * 0.24;\n    col += lueur_col * halo * pres;\n\n    // La brume : meme grammaire que dans BRUME, une nappe lente qui derive et\n    // qui pese sur le bas de l'image.\n    float hz = fbm(vec2(uv.x * 1.6 + t * 0.012, uv.y * 3.0 - t * 0.006), 3);\n    float nappe = smoothstep(0.16, -0.50, uv.y) * (0.35 + 0.65 * hz);\n    col = mix(col, brume_col, clamp(nappe * (0.24 + 0.22 * e), 0.0, 1.0));\n\n    // La grille est deformee par un bruit tres lent : elle ne se referme\n    // jamais sur le meme motif.\n    vec2 wp = uv;\n    wp += (vec2(fbm(uv * 1.5 + vec2(t * 0.010, 0.0), 3),\n                fbm(uv * 1.5 + vec2(0.0, 3.7 - t * 0.008), 3)) - 0.5) * 0.15;\n\n    // Bandes horizontales decalees : c'est la que se lit l'instabilite.\n    wp.x += grain_rowshift(floor(uv.y * 14.0 + 30.0), t);\n\n    // Le centre reste calme : c'est la que le texte se lit.\n    float rad  = length(uv * vec2(0.72, 1.0));\n    float peri = smoothstep(0.12, 0.46, rad);\n\n    // e densifie les cellules : d'une sur dix a une sur trois.\n    float dens = mix(0.11, 0.32, e);\n\n    // Deux nappes d'echelles differentes, la seconde tournee : ensemble elles\n    // ne dessinent plus une grille reguliere.\n    float c = grain_cells(wp, t, vec2(0.052, 0.034), dens, 0.0);\n    c += grain_cells(wp * rot(0.42) + vec2(11.3, -4.7), t, vec2(0.088, 0.058),\n                     dens * 0.80, 17.0) * 0.75;\n    c = clamp(c, 0.0, 1.0);\n\n    // Les cellules s'amassent la ou la brume est epaisse, elles pesent vers le\n    // bas et se tiennent pres de la lueur : des amas qui se defont lentement.\n    c *= 0.35 + 0.65 * hz;\n    c *= peri;\n    c *= 0.18 + 0.82 * smoothstep(0.42, -0.45, uv.y);\n    c *= 0.55 + 0.55 * exp(-ld * 2.4);\n\n    vec3 cc = mix(brume_col, lueur_col * 0.62, exp(-ld * 2.2) * 0.50);\n    col += cc * c * (0.75 + 0.35 * e);\n\n    // Lignes de balayage : a peine visibles, elles derivent a 0.11 Hz.\n    float scan = 0.5 + 0.5 * sin(uv.y * 190.0 - t * 0.7);\n    col *= 0.940 + 0.060 * scan;\n    col += lueur_col * 0.018 * scan * peri * pres;\n\n    // Grain fin : il derive d'une cellule toutes les vingt secondes. C'est une\n    // matiere, pas un scintillement.\n    float fg = noise2(uv * 90.0 + vec2(t * 0.050, -t * 0.037));\n    col += (fg - 0.5) * 0.018 * (0.45 + 0.55 * peri);\n\n    // Meme tramage fixe que BRUME.\n    col += (hash21(uv * 511.0) - 0.5) * 0.004;\n\n    return clamp(col, 0.0, 0.26);\n}\n\n// ===== perte.glsl =====\n// =====================================================================\n//  PERTE - deux scenes de manque : eclipse, voidwell\n//\n//  Meme main pour les deux : la meme brume exponentielle mange la\n//  lumiere avec la distance, la meme gamme de gris froids (l'encre du\n//  ciel) et le meme blanc a peine tiede pour l'unique source, la meme\n//  lenteur (tout se compte en dizaines de secondes).\n// =====================================================================\n\n\n// ---------------------------------------------------------------------\n//  ECLIPSE\n//  Un disque noir devant une source cachee, un filet de lumiere autour\n//  de lui, et au-dessous une mer sombre qui en porte un chemin de\n//  reflets brises. Il y a une lumiere, elle est derriere quelque chose.\n// ---------------------------------------------------------------------\n\n// attenuation par la brume : la meme courbe sert a la mer, au halo et\n// au vignettage. C'est elle qui donne le grain commun aux deux scenes.\nfloat eclipse_fog(float d) {\n    return exp(-d * d * 0.55 - d * 0.35);\n}\n\n// l'encre du ciel : le haut se perd dans le noir, le bas garde un\n// reste de matiere\nvec3 eclipse_ink(float y) {\n    return mix(vec3(0.016, 0.018, 0.023),\n               vec3(0.002, 0.002, 0.004),\n               smoothstep(-0.35, 1.05, y));\n}\n\n// la seule couleur de lumiere autorisee : un blanc gris a peine tiede\nvec3 eclipse_light() {\n    return vec3(0.255, 0.243, 0.216);\n}\n\n// les eclats sur l'eau : une phase de houle deformee par le bruit, si\n// bien que les cretes restent des lignes au lieu de se dissoudre en\n// taches, et un second bruit qui les casse en tirets - rien n'est\n// continu sur l'eau. det coupe le detail au loin pour que l'horizon ne\n// scintille pas ; le temps recu ici est deja ralenti par e, a e = 0 la\n// mer est presque figee.\nfloat eclipse_glint(vec2 w, float t, float det, float e) {\n    float warp = fbm(vec2(w.x * 0.30, w.y * 0.28 - t * 0.030), 3);\n    float c = max(sin(w.y * 4.20 + warp * 3.0 - t * 0.090), 0.0);\n    float c2 = c * c;\n    float crest = c2 * c;\n    float lo = 0.40 + 0.12 * (1.0 - e);\n    float dash = smoothstep(lo, lo + 0.32,\n                 fbm(vec2(w.x * 2.00, w.y * 0.34 - t * 0.045), 2));\n    return crest * dash * det;\n}\n\nvec3 scene_eclipse(vec2 uv, float t, float e) {\n    float hz = -0.08;                 // ligne d'horizon, sous le texte\n    vec2  c  = vec2(-0.24, 0.52);     // le disque, haut et decentre\n    float R  = 0.16;                  // rayon du disque noir\n\n    vec2  d  = uv - c;\n    float r  = length(d);\n    float a  = atan(d.y + 0.000001, d.x + 0.000001);\n\n    // ciel\n    vec3 col = eclipse_ink(uv.y);\n\n    // nappes de brume hautes, tres lentes, a peine lisibles, plus\n    // denses en approchant de l'horizon\n    float veil = fbm(vec2(uv.x * 0.55 + t * 0.008, uv.y * 1.30 - t * 0.004), 3);\n    col += vec3(0.012, 0.013, 0.017) * veil * smoothstep(0.75, -0.15, uv.y);\n\n    // irregularite de l'anneau : la couronne n'est pas egale, elle\n    // derive d'un tour de disque en une poignee de minutes\n    float bead = smoothstep(0.20, 0.78,\n                 fbm(vec2(cos(a), sin(a)) * 2.10\n                     + t * (0.006 + 0.014 * e), 3));\n\n    // couronne : une respiration de lumiere, jamais un halo franc,\n    // et rien ne deborde a l'interieur du disque\n    float outside = smoothstep(R - 0.006, R + 0.004, r);\n    float corona  = exp(-max(r - R, 0.0) * 9.0) * 0.055\n                  + exp(-max(r - R, 0.0) * 2.2) * 0.016;\n    col += eclipse_light() * corona * (0.40 + 0.60 * bead) * outside;\n\n    // le disque mange le ciel qu'il recouvre\n    col *= 1.0 - 0.95 * smoothstep(R + 0.006, R - 0.002, r);\n\n    // l'anneau : un filet. e l'epaissit d'un cheveu, pas davantage.\n    float w    = 0.0070 + 0.0026 * e;\n    float ring = smoothstep(w, w * 0.25, abs(r - R));\n    col += eclipse_light() * ring * (0.35 + 0.65 * bead) * 0.92;\n\n    // -- la mer -------------------------------------------------------\n    // perspective simple : la profondeur explose vers l'horizon.\n    // zz est une profondeur comprimee : la houle garde du grain pres du\n    // bord bas sans se hacher en moire pres de l'horizon.\n    float dy    = max(hz - uv.y, 0.0);\n    float depth = min(0.16 / (dy + 0.012), 11.0);\n    float zz    = pow(depth, 0.55) * 10.0;\n    float det   = 1.0 / (1.0 + depth * depth * 0.55);\n    float att   = eclipse_fog(depth * 0.42);\n    vec2  wp    = vec2(uv.x * zz * 4.20, zz);\n\n    // temps de la mer : e est l'amplitude du mouvement, pas la\n    // luminosite. A e = 0 l'eau bouge a peine.\n    float tw = t * (0.15 + 0.85 * e);\n\n    // la colonne de reflets sous le disque : etroite a l'horizon,\n    // largement etalee en bas d'ecran. e la fait deriver.\n    float sig  = 0.045 + 0.42 * dy;\n    float wob  = (fbm(vec2(uv.y * 2.60, tw * 0.050), 2) - 0.5)\n               * (0.05 + 0.35 * e) * dy;\n    float px   = (uv.x - c.x + wob) / sig;\n    float path = exp(-px * px);\n\n    float glint = eclipse_glint(wp, tw, det, e) * path * att;\n\n    vec3 water = vec3(0.006, 0.007, 0.010) * (0.30 + 0.70 * att);\n    water += eclipse_light() * (glint * (0.20 + 0.30 * e) + path * att * 0.030);\n\n    float sea = smoothstep(hz + 0.004, hz - 0.004, uv.y);\n    col = mix(col, water, sea);\n\n    // la brume posee sur l'horizon, un peu plus dense sous la colonne :\n    // c'est elle qui donne la silhouette de la scene\n    float colonne = exp(-((uv.x - c.x) / 0.55) * ((uv.x - c.x) / 0.55));\n    col += vec3(0.022, 0.025, 0.031)\n         * exp(-abs(uv.y - hz) * 26.0) * (0.28 + 0.72 * colonne);\n\n    // vignettage : la meme brume, appliquee a la distance au centre\n    col *= eclipse_fog(max(length(uv) - 0.45, 0.0) * 0.85);\n\n    return min(max(col, 0.0), vec3(0.26));\n}\n\n\n// ---------------------------------------------------------------------\n//  VOIDWELL\n//  Un puits circulaire vu de face. Des anneaux concentriques qui se\n//  serrent vers un centre parfaitement noir, une lumiere qui rase la\n//  paroi d'un seul cote, et des bords avales par la brume. Pas de fond.\n//  C'est le vide : quand il n'y a rien a dire.\n// ---------------------------------------------------------------------\n\n// meme courbe d'attenuation que l'eclipse : profondeur, bords, tout\n// s'eteint de la meme facon\nfloat voidwell_fog(float d) {\n    return exp(-d * d * 0.55 - d * 0.35);\n}\n\n// meme blanc a peine tiede que l'eclipse\nvec3 voidwell_light() {\n    return vec3(0.250, 0.240, 0.216);\n}\n\n// profil d'un anneau : un liseret fin mais doux, jamais une rayure.\n// Cosinus eleve a la puissance neuf : ca reste lisse et ca ne moire pas\n// quand les anneaux se resserrent.\nfloat voidwell_band(float q) {\n    float c = 0.5 + 0.5 * cos(6.2831853 * q);\n    float c2 = c * c;\n    float c4 = c2 * c2;\n    return c4 * c4 * c;\n}\n\nvec3 scene_voidwell(vec2 uv, float t, float e) {\n    // e fait tourner les anneaux : environ un degre par minute au repos,\n    // cinq degres par minute au maximum. Rien de plus.\n    float spin = t * (0.00035 + 0.00120 * e);\n\n    vec2  p = uv * rot(spin);\n    float r = length(uv);\n    float a = atan(p.y + 0.000001, p.x + 0.000001);\n\n    // la maconnerie n'est pas parfaite : les anneaux ondulent un peu,\n    // et c'est cette irregularite qui rend la rotation perceptible\n    float warp = fbm(vec2(cos(a), sin(a)) * 1.60 + 7.0, 3) - 0.5;\n    float rr   = max(r * (1.0 + 0.100 * warp), 0.040);\n\n    // coordonnee de profondeur : en 1/r, les anneaux se serrent\n    // indefiniment vers le centre. Une respiration tres lente, pas un\n    // defilement.\n    float breath = 0.045 * sin(t * 0.055) * (0.30 + 0.70 * e);\n    float q = 1.45 / rr + breath;\n\n    float ring = voidwell_band(q);\n\n    // la lumiere tombe d'en haut a gauche et ne prend que sur la paroi\n    // opposee : un seul cote du puits existe, le reste est noir\n    vec2  L   = normalize(vec2(-0.55, 0.84));\n    vec2  dir = uv / max(r, 0.0001);\n    float lit = 0.05 + 0.95 * pow(max(0.5 - 0.5 * dot(dir, L), 0.0), 2.6);\n\n    // plus on descend dans le puits, plus la brume mange les anneaux\n    float deep = voidwell_fog(q * 0.20);\n\n    // le centre est parfaitement noir : le puits n'a plus de fond, et\n    // c'est la que le texte se lit\n    float core = smoothstep(0.10, 0.32, r);\n\n    // les bords sont avales : pas de decor autour, juste l'extinction\n    float edge = voidwell_fog(max(r - 0.35, 0.0) * 2.00);\n\n    // le haut se perd, le bas garde un peu de matiere\n    float grav = 0.30 + 0.70 * smoothstep(0.95, -0.35, uv.y);\n\n    // salissures tres lentes sur la paroi, elles tournent avec elle\n    float stain = 0.62 + 0.38\n                * fbm(vec2(cos(a), sin(a)) * 2.40 + vec2(q * 0.28, 0.0), 3);\n\n    vec3 col = voidwell_light()\n             * (ring * lit * deep * core * edge * stain * grav) * 1.15;\n\n    // poussiere de brume, absente au centre pour ne pas grisailler le\n    // texte, avalee par les bords comme le reste\n    float dust = fbm(vec2(uv.x * 0.90 + t * 0.006, uv.y * 0.90 - t * 0.004), 3);\n    col += vec3(0.009, 0.010, 0.013) * dust * grav * edge * core;\n\n    return min(max(col, 0.0), vec3(0.26));\n}\n\n// ===== pluie.glsl =====\n// ===========================================================================\n// pluie.glsl -- LA PLUIE\n//\n// Ce qui se relache. Pas la tristesse -- « eclipse » la porte deja, et une\n// pluie qui voudrait dire « tu vas mal » serait un verdict peint sur le fond.\n// Celle-ci dit le temps qui tombe : quelque chose sort, ca coule, et la piece\n// est seche. C'est une scene ou l'on est A L'ABRI, ce qui est tout ce qu'elle\n// affirme.\n//\n// Trois plans, comme on regarde vraiment la pluie : les gouttes proches et\n// rapides, les moyennes, la nappe lointaine qui n'est plus qu'un voile. Et en\n// bas, le sol mouille -- des ronds qui s'ouvrent et s'effacent, parce que\n// c'est la qu'on voit qu'il pleut, pas dans le ciel.\n//\n// Cadre : uv.y de -0.5 en bas a +0.5 en haut. Le sol occupe le sixieme bas.\n//\n// e regle la DENSITE : une pluie fine ou une averse. Pas la luminosite --\n// une averse n'est pas plus claire, elle est plus pleine.\n// ===========================================================================\n\nconst float pluie_SOL = -0.33;   // la ligne du sol mouille\n\nvec3 pluie_tone(vec3 c) {\n    c = max(c, 0.0);\n    return 0.27 * (1.0 - exp(-c / 0.27));\n}\n\n// Une nappe de traits qui tombent.\n//\n// L'astuce tient en deux lignes : on decoupe le plan en colonnes, chaque\n// colonne recoit une phase et une vitesse tirees de son numero, et le trait\n// vit dans le bas de sa cellule verticale. Une colonne sur trois environ porte\n// une goutte -- une pluie ou chaque colonne coule est un rideau, pas une pluie.\nfloat pluie_nappe(vec2 uv, float t, float ech, float vitesse, float seed, float densite)\n{\n    vec2 p = uv * ech;\n    p.x += p.y * 0.13;                       // l'oblique : il ne pleut jamais droit\n    float col = floor(p.x);\n    float ph = hash11(col * 1.37 + seed * 57.3);\n    // Une colonne sur trois porte une goutte, et le seuil descend quand ca\n    // tombe plus fort.\n    if (hash11(col * 2.11 + seed * 13.7) > densite) return 0.0;\n\n    float y = fract(p.y * 0.62 - t * vitesse * (0.75 + 0.5 * ph) + ph);\n    float x = fract(p.x) - 0.5;\n\n    // Le trait : fin en travers, court dans le sens de la chute, avec une tete\n    // plus dense que la queue.\n    float largeur = smoothstep(0.5, 0.0, abs(x) * 11.0);\n    float longueur = smoothstep(0.30, 0.0, y) * smoothstep(0.0, 0.05, y);\n    return largeur * longueur * (0.55 + 0.45 * ph);\n}\n\n// Les ronds sur le sol. Six impacts qui se relancent chacun a leur rythme ;\n// chaque rond s'ouvre en s'effacant, ce qui est ce que fait un rond dans une\n// flaque. Ecrases verticalement : on regarde le sol de biais, pas d'au-dessus.\nfloat pluie_ronds(vec2 uv, float t, float e)\n{\n    float s = 0.0;\n    for (int i = 0; i < 9; i++) {\n        float fi = float(i);\n        float periode = 0.9 + hash11(fi * 7.3) * 1.4;\n        float k = floor(t / periode + fi * 0.37);       // le numero de l'impact\n        float age = fract(t / periode + fi * 0.37) * periode;\n\n        // Chaque impact tombe ailleurs : la position vient du NUMERO, pas de\n        // l'indice -- sinon les memes ronds reapparaissent toujours aux memes\n        // endroits, et l'oeil le voit en dix secondes.\n        vec2 c = vec2((hash11(k * 3.1 + fi * 19.0) - 0.5) * 1.8,\n                      pluie_SOL - 0.012 - hash11(k * 5.7 + fi * 23.0) * 0.14);\n\n        float r = length((uv - c) * vec2(1.0, 3.4));\n        /*\n         * PETITS ET BREFS. Grands et lents, ce sont des cercles dessines, pas\n         * des impacts : on lit le trace au lieu de lire la pluie. Un rond de\n         * goutte s'ouvre sur deux centiemes de cadre et a disparu en une\n         * seconde -- c'est le NOMBRE qui fait la pluie, pas la taille.\n         */\n        float rayon = age * 0.026;\n        // Le carre a la main : `pow` sur une base negative n'est pas defini en\n        // GLSL, et `r - rayon` est negatif a l'interieur du rond.\n        float dr = (r - rayon) * 150.0;\n        float anneau = exp(-dr * dr);\n        s += anneau * exp(-age * 3.4) * (0.6 + 0.4 * e);\n    }\n    return s;\n}\n\nvec3 scene_pluie(vec2 uv, float t, float e)\n{\n    // Gris froids, comme le reste de l'application, mais un peu plus bleus :\n    // c'est la seule scene ou l'air lui-meme est mouille.\n    vec3 ciel_haut = vec3(0.008, 0.011, 0.019);\n    vec3 ciel_bas  = vec3(0.036, 0.046, 0.062);\n    vec3 eau       = vec3(0.150, 0.176, 0.215);\n    vec3 sol       = vec3(0.013, 0.016, 0.022);\n\n    float densite = 0.26 + 0.22 * e;\n\n    // ---- le ciel ----------------------------------------------------------\n    float v = smoothstep(0.60, pluie_SOL, uv.y);\n    vec3 col = mix(ciel_haut, ciel_bas, v * v);\n\n    // Des nuages bas qui glissent. Tres etires, tres lents : ce qui donne\n    // l'impression de pluie, ce n'est pas leur forme, c'est qu'ils bougent\n    // tous ensemble et pas a la meme vitesse.\n    for (int i = 0; i < 3; i++) {\n        float fi = float(i);\n        float n = fbm(vec2(uv.x * (1.1 + fi * 0.6) + t * (0.016 + fi * 0.009) + fi * 31.0,\n                           uv.y * 3.2 - t * 0.004 + fi * 7.0), 4);\n        float bande = smoothstep(0.55, -0.10, uv.y - fi * 0.10);\n        col += vec3(0.026, 0.031, 0.040) * bande * smoothstep(0.40, 0.85, n) * (0.9 - fi * 0.22);\n    }\n\n    // Une lueur diffuse en haut a gauche : une ville, une fenetre, on ne sait\n    // pas. Sans elle, la pluie tombe dans du noir et ne se voit pas.\n    float lueur = exp(-length((uv - vec2(-0.30, 0.30)) * vec2(0.7, 1.1)) * 2.1);\n    col += vec3(0.052, 0.058, 0.070) * lueur;\n\n    // ---- la pluie ---------------------------------------------------------\n    // Trois plans. Le lointain est presque un voile, le proche a des traits\n    // qu'on distingue. Le proche est aussi le plus rare : trop de gouttes\n    // devant le texte et on ne lit plus.\n    float p0 = pluie_nappe(uv, t, 46.0, 0.85, 1.0, densite * 1.20);   // loin\n    float p1 = pluie_nappe(uv, t, 24.0, 1.35, 2.0, densite * 0.85);   // milieu\n    float p2 = pluie_nappe(uv, t, 12.0, 2.10, 3.0, densite * 0.45);   // pres\n\n    // Elle s'arrete au sol : une goutte qui traverse le sol n'est plus de la\n    // pluie, c'est une rayure sur l'ecran.\n    float auDessus = smoothstep(pluie_SOL - 0.01, pluie_SOL + 0.03, uv.y);\n    float traits = (p0 * 0.30 + p1 * 0.52 + p2 * 0.80) * auDessus;\n    col += eau * traits * (0.45 + 0.30 * e);\n\n    // ---- le sol -----------------------------------------------------------\n    /*\n     * LE BORD NE DOIT PAS ETRE UN TRAIT. Ferme sur quelques millimes, la ligne\n     * du sol traverse tout l'ecran comme un mur ; on la laisse donc respirer,\n     * et une bande sombre juste au-dessus fait le pied de l'image.\n     */\n    float m = smoothstep(pluie_SOL + 0.016, pluie_SOL - 0.010, uv.y);\n    col *= 1.0 - 0.30 * exp(-max(0.0, uv.y - pluie_SOL) * 26.0);\n    // Le reflet : le ciel repris a l'envers, ecrase et assombri. C'est ce qui\n    // fait que le sol est MOUILLE et pas seulement sombre.\n    vec2 mir = vec2(uv.x, pluie_SOL - (uv.y - pluie_SOL) * 2.6);\n    float lueurMir = exp(-length((mir - vec2(-0.30, 0.30)) * vec2(0.7, 1.1)) * 2.1);\n    vec3 plan = sol + vec3(0.040, 0.046, 0.058) * lueurMir * 0.55;\n    // Le reflet se brouille quand on s'eloigne du bord : la flaque n'est pas\n    // un miroir.\n    plan *= 0.75 + 0.25 * fbm(vec2(uv.x * 7.0, uv.y * 26.0 + t * 0.09), 3);\n    plan += eau * pluie_ronds(uv, t, e) * 0.55;\n    col = mix(col, plan, m);\n\n    // ---- la finition ------------------------------------------------------\n    col *= mix(0.34, 1.0, smoothstep(0.55, -0.10, uv.y));\n    col *= 0.95 + 0.05 * sin(t * 0.047);\n\n    return pluie_tone(col);\n}\n";
